def traitementCalculerSuperficie(source, sortie,
                                 champ_superficie='superficie'):
    algo_name, algo_simplifie = "native:fieldcalculator", \
                                "Calculer superficie..."
    if (champ_superficie == 'surface_ut_dans_parcelle'):
        CHEMIN = os.path.dirname(sortie)
        CIBLE = os.path.basename(sortie)
        la_sortie = os.path.join(CHEMIN, 'TMP_' + CIBLE)
    else:
        la_sortie = sortie
    result = processing.run(algo_name,
        {'INPUT': source, 'OUTPUT': la_sortie,
         'FIELD_NAME': champ_superficie, 'FIELD_TYPE': 1,
         'FIELD_LENGTH': 10, 'FIELD_PRECISION': 0,
         'FORMULA': 'to_int($area)'})
    if (champ_superficie == 'surface_ut_dans_parcelle'):
        result = processing.run(algo_name,
         {'INPUT': la_sortie, 'OUTPUT': sortie,
          'FIELD_NAME': 'pourcent_ut_dans_parcelle',
          'FIELD_TYPE': 1, 'FIELD_LENGTH': 10, 'FIELD_PRECISION': 0,
          'FORMULA': '"surface_ut_dans_parcelle"/"superficie"*100'})

    if result is None:
        monPrint("Erreur bloquante durant processing {0}".
                 format(algo_simplifie), T_ERR)
        erreurTraitement(algo_name)
    return result


