    def initialiserCombo(self, comboAInitialiser, LISTE_VALEURS, UNE_VALEUR,
                         libelleErreur=None):
        """Initialise un combo avec une liste de valeur et avec la
        position de la valeur correspondante trouvée dans Settings
        """
        comboAInitialiser.setCurrentIndex(0)
        if len(LISTE_VALEURS) == 0:
            comboAInitialiser.clear()
            if libelleErreur is not None:
                monPrint(self.tr("Pas de liste {0} pré défini".
                                 format(libelleErreur)), T_WAR, "BAR", self)
        else:
            comboAInitialiser.clear()
            comboAInitialiser.addItems(LISTE_VALEURS)
            # Retrouver le mode de trace dans  settings
            for idx, valeur in enumerate(LISTE_VALEURS):
                if (valeur == UNE_VALEUR):
                    comboAInitialiser.setCurrentIndex(idx)
                    break

    def initialiserListeMultiple(self, listWidget, LISTE_VALEURS_POSSIBLE,
                                 LISTE_VALEURS, libelleErreur):
        """Initialise unne liste de valeur et avec la liste des valeurs
        correspondantes trouvées dans Settings
        """
        if len(LISTE_VALEURS_POSSIBLE) == 0:
            # listeAInitialiser.clear()
            monPrint(self.tr("Pas de liste {0} pré défini".
                             format(libelleErreur)), T_WAR, "BAR", self)
            return
        if len(LISTE_VALEURS) == 0:
            monPrint(self.tr("Pas de liste {0} à sélectionner".
                             format(libelleErreur)), T_WAR, "BAR", self)
        else:
            listWidget.clear()
            listWidget.addItems(LISTE_VALEURS_POSSIBLE)

            for i in LISTE_VALEURS:
                matching_items = listWidget.findItems(i, Qt.MatchExactly)
                for item in matching_items:
                    item.setSelected(True)

