    def ouvrirProjetETGroupe(self, nomDuGroupe):
        """ Ouvrir projet et un groupe"""

        # Vérification du projet ouverte
        monProjet = QgsProject.instance()
        if monProjet.fileName() is None or monProjet.fileName() == "":
            monPrint("Projet en cours de création", T_WAR)
        else:
            monPrint("Projet ouvert {}".format(monProjet.fileName()))

        root = monProjet.layerTreeRoot()
        # Création du groupe jointure_date
        dateMaintenant = datetime.now()
        nomGroupe = nomDuGroupe + " du " + \
            dateMaintenant.strftime("%d %b à %Hh%M:%S")
        temporaireGroupe = QgsLayerTreeGroup(nomGroupe)
        # Positionner en haut de root
        root.addChildNode(temporaireGroupe)
        nouveauGroupe = temporaireGroupe.clone()
        root.insertChildNode(0, nouveauGroupe)
        root.removeChildNode(temporaireGroupe)
        return monProjet, nouveauGroupe

    def fusionnerJointure(self, cheminCompletParcelle, jointureChoisie):
        """ Selon les tables déja ouverte dans le projet :
        ouverture si necessaire des différents cas de délimiteurs
        Jointure par QGIS """
        REPERTOIRE_GPKG = self.Repertoire_lineEdit.text()
        CHEMIN_SYNCHRONISATION = quel_chemin_synchro(REPERTOIRE_GPKG, REP_SYN)

        # Vérification du projet ouverte
        monProjet, nouveauGroupeJointure = self.ouvrirProjetETGroupe(
            MonParcellaire_JOI)
        # Ouverture du vecteur parcelle
        parcelle = QgsVectorLayer(cheminCompletParcelle,
            MonParcellaire_PAR + SEP_U + MonParcellaire_JOI, 'ogr')
        monProjet.addMapLayer(parcelle, False)
        nouveauGroupeJointure.addLayer(parcelle)

        # Recherche delimiteur
        delimiteur, csv, nomCsv = self.rechercherDelimiteurJointure(
            jointureChoisie, "No Pandas")
        nomCourtJointure = os.path.basename(jointureChoisie)

        monPrint("Délimiteur identifié {0} pour {1}".
                 format(delimiteur, nomCourtJointure), T_OK)
        monProjet.addMapLayer(csv, False)
        nouveauGroupeJointure.addLayer(csv)

        # Jointure
        attributsSelectionnes = \
            self.AttributsAJoindre_listWidget.selectedItems()
        attributsAJoindre = []
        for positionAttribut in range(len(attributsSelectionnes)):
            attributsAJoindre.append(str(
                self.AttributsAJoindre_listWidget.selectedItems()[
                    positionAttribut
                ].text()))
        # monPrint("Attributs à joindre {}".format(attributsAJoindre))
        # Liste des champs dans csv
        nomColonnes, _ = self.lireAttributsJointure(jointureChoisie)
        attributsAJoindreOrdonne = []
        for col in nomColonnes:
            if col in attributsAJoindre:
                if col != MonParcellaireNomAttribut:
                    attributsAJoindreOrdonne.append(col)

        champVecteur = MonParcellaireNomAttribut
        maJointure = QgsVectorLayerJoinInfo()
        champCsv = self.AttributJointure_comboBox.currentText()
        maJointure.setJoinFieldName(champCsv)
        maJointure.setTargetFieldName(champVecteur)
        maJointure.setUsingMemoryCache(True)
        maJointure.setPrefix("")
        maJointure.setJoinLayer(csv)
        # Récupérer les champs de jointure
        maJointure.setJoinFieldNamesSubset(attributsAJoindreOrdonne)
        parcelle.addJoin(maJointure)
        affec_sans_suite = os.path.join(CHEMIN_SYNCHRONISATION,
                                  MonParcellaire_AFF_SANS_SUITE + EXT_geojson)
        traitementSauverEcraser(parcelle, affec_sans_suite)
        return jointureChoisie, attributsAJoindreOrdonne, affec_sans_suite

    def rechercherExtensionEncodage(self, repertoireGPKG,
                                    nom_jointure=MonParcellaire_JOI):
        """ Traite les différents cas d'extensions
            Rend la première jointure disponbile et la transforme
            en UTF-8 si necessaire
            ou None si il n'est existe aucune"""
        if not os.path.isdir(repertoireGPKG):
            erreurRepertoire(repertoireGPKG)
        for extension in EXTENSIONS_CONNUES:
            CHEMIN_JOINTURE = nommageVecteur(repertoireGPKG,
                                             nom_jointure, extension,
                                             "Ne doit pas preexister")
            if os.path.isfile(CHEMIN_JOINTURE):
                break
        if not os.path.isfile(CHEMIN_JOINTURE):
            monWarning = "Aucune jointure disponible parmi {}. ".\
                         format(EXTENSIONS_CONNUES)
            monWarning = monWarning + \
                "Déposez la jointure dans votre référentiel : répertoire {}".\
                format(repertoireGPKG)
            monPrint(monWarning, T_WAR, "BAR", self)
            monPrint(monWarning, T_WAR)
            return None
        # Détection encodage
        monFile = open(CHEMIN_JOINTURE, "rb")
        rawdata = monFile.read()
        detection = chardet.detect(rawdata)
        monFile.close()
        if detection['encoding'] == 'utf-8':
            CHEMIN_JOINTURE_UTF = CHEMIN_JOINTURE
        else:
            CHEMIN_JOINTURE_UTF = os.path.join(repertoireGPKG,
                  nom_jointure + "_UTF-8" + extension)
            monFile_UTF = open(CHEMIN_JOINTURE_UTF, "wb")
            monPrint("Encodage {0} pour cette jointure pris".
                     format(detection['encoding']),
                     "en charge par Mon Parcellaire",
                     T_OK)
            dataUTF = rawdata.decode(detection['encoding']).encode("utf-8")
            monFile_UTF.write(dataUTF)
            monFile_UTF.close()
        return CHEMIN_JOINTURE_UTF

    def rechercherDelimiteurJointure(self, CHEMIN_JOINTURE, mode="Pandas"):
        """ Traite les différents cas de délimiteurs avec pandas ou QGIS"""
        if VERSION_PANDAS is not None and mode == "Pandas":
            lesDelimiteurs = " "
            for delimiteur in DELIMITEURS_CONNUS:
                if delimiteur != '\t':
                    lesDelimiteurs = lesDelimiteurs + delimiteur + " "
                else:
                    lesDelimiteurs = lesDelimiteurs + "TABULATION "
                try:
                    dfJointure = pd.read_csv(CHEMIN_JOINTURE, sep="{}".
                                             format(delimiteur))
                except:
                    monPrint('Délimiteur "{0}" ne convient pas au csv {1}'.
                             format(delimiteur, CHEMIN_JOINTURE))
                    continue
                break
            if dfJointure.empty:
                erreurJointureDelimeteurs(CHEMIN_JOINTURE, lesDelimiteurs)
                return None, None, None
            return delimiteur, dfJointure, None
        else:
            for delimiteur in DELIMITEURS_CONNUS:
                nomCsv = "file:///{1}?delimiter={0}".\
                    format(delimiteur, CHEMIN_JOINTURE)
                try:
                    csv = QgsVectorLayer(nomCsv,
                                         MonParcellaire_JOI,
                                         'delimitedtext')
                except:
                    monPrint("Délimiteur {0} ne convient pas au csv {1}".
                             format(delimiteur, nomCsv))
                    continue
                break
            # TODO Vx: attraper erreur ?
            return delimiteur, csv, nomCsv

    def lireAttributsJointure(self, CHEMIN_JOINTURE):
        """ Lecture de la jointure dans Pandas, pour trouver
        attributs unique et avec doubles"""
        nomColonnes = []
        nomColonnesUniques = []
        if VERSION_PANDAS is not None:
            _, dfJointure, _ = \
                self.rechercherDelimiteurJointure(CHEMIN_JOINTURE)
            if dfJointure.empty:
                return nomColonnes, nomColonnesUniques
            # monPrint("Liste des colonnes {}".format(listeColonnes))
            for col in dfJointure.columns:
                if col != MonParcellaireNomAttribut:
                    nomColonnes.append(col)
                listeJointureBrute = dfJointure[col].sort_values()
                listeJointureUnique = \
                    dfJointure[col].sort_values().unique()
                if len(listeJointureBrute) == len(listeJointureUnique):
                    unique = True
                else:
                    unique = False
                if unique:
                    nomColonnesUniques.append(col)
                    # monPrint("Colonne {0} est unique".format(col))
        else:
            _, layer, _ = self.rechercherDelimiteurJointure(CHEMIN_JOINTURE)
            # TEST: à vérifier
            if layer is None:
                return nomColonnes, nomColonnesUniques
            for field in layer.fields():
                nomColonnes.append(field.name())
            # Sans Pandas : mode dégradé pas de recherche des uniques
            nomColonnesUniques = nomColonnes
        if nomColonnesUniques == []:
            monPrint("Aucun attribut de cette jointure"
                     " n'est unique: jointure impossible", T_ERR)
            monPrint("Aucun attribut de cette jointure"
                     " n'est unique: jointure impossible",
                     T_ERR, T_BAR, self)
            # Décocher le choix de jointure
            self.Jointure_checkBox.setChecked(Qt.Unchecked)
        return nomColonnes, nomColonnesUniques

    def extraireVignesMesParcelles(self):
        """ Ouvrir CSV Mes Parcelles
        Dupliquer dans nom le champ nom_parcelle
        Selectionnées les vignes
        """

        REPERTOIRE_GPKG = self.Repertoire_lineEdit.text()
        CHEMIN_SYNCHRONISATION = quel_chemin_synchro(REPERTOIRE_GPKG, REP_SYN)
        monProjet, nouveauGroupeMP =\
            self.ouvrirProjetETGroupe(MonParcellaire_MP)
        cheminCompletMesParcelle = self.Mes_Parcelles_lineEdit.text()
        uri = "file:///" + cheminCompletMesParcelle + \
              "?delimiter={}&wktField={}".format(",", "geom")
        mes_parcelles = QgsVectorLayer(uri,
            MonParcellaire_MP, 'delimitedtext')
        monProjet.addMapLayer(mes_parcelles, False)
        # nouveauGroupeMP.addLayer(mes_parcelles)
        # Forcer EPSG 2154 QgsCoordinateReferenceSystem constructor deprecated
        mes_parcelles.setCrs(
            QgsCoordinateReferenceSystem('EPSG:' + str(ID_DESTINATION_CRS)))
        monProjet.addMapLayer(mes_parcelles, False)
        nouveauGroupeMP.addLayer(mes_parcelles)

        # Sauver en geojson
        try:
            nom_toutes_parcelles = os.path.join(
                CHEMIN_SYNCHRONISATION,
                "MES_PARCELLES_TOUTES" + EXT_geojson)
            traitementSauverEcraser(uri, nom_toutes_parcelles)
            toutes_parcelles = QgsVectorLayer(nom_toutes_parcelles,
                    MesParcelles_GJ, "ogr")
            monProjet.addMapLayer(toutes_parcelles, False)
        except:
            erreurGeojsonOuvert(nom_toutes_parcelles)
        # Filtrer les seules vignes
        try:
            traitementSelectionnerVignes(nom_toutes_parcelles)
            selection_input = QgsProcessingFeatureSourceDefinition(
                nom_toutes_parcelles,
                selectedFeaturesOnly=True,
                featureLimit=-1,
                geometryCheck=QgsFeatureRequest.GeometryAbortOnInvalid)
            nom_vignes_tous_attributs = os.path.join(CHEMIN_SYNCHRONISATION,
                "MES_PARCELLES_TOUS_ATTRIBUTS" + EXT_geojson)
            traitementSauverEcraser(selection_input, nom_vignes_tous_attributs)
            # Vérifier si on a une seule cave
            dfVignes = gpd.read_file(nom_vignes_tous_attributs)
            # Try KeyError: pas de champ 'cave_transfert'
            try:
                available_cave = dfVignes[
                    'cave_transfert'].sort_values().unique()
            except KeyError:
                monPrint("= Info = Pas de caves.")
            else:
                monPrint("= Info = Les caves {}.".format(available_cave))
            # TODO puis extraire les vignes NULL qui n'ont pas de cave
            toutes_attr_vignes = QgsVectorLayer(nom_vignes_tous_attributs,
                    MonParcellaireFiltre_GJ, "ogr")
            monProjet.addMapLayer(toutes_attr_vignes, False)
            # nouveauGroupeMP.addLayer(toutes_attr_vignes)
        except:
            aPrint = "Vecteur {} ne convient pas ".format(nom_toutes_parcelles)
            aPrint = aPrint + "pour la sélection des vignes"
            monPrint(aPrint, T_ERR)
            erreurTraitement("Sélection vignes")
        try:
            # Garder les colonnes utiles de Mes Parcelles pour Mon Parcellaire
            nom_vignes_mini_attributs = os.path.join(CHEMIN_SYNCHRONISATION,
                "MES_PARCELLES_MINI_ATTRIBUTS" + EXT_geojson)
            traitementGarderChamps(nom_vignes_tous_attributs,
                                   nom_vignes_mini_attributs)
            nom_vignes = os.path.join(CHEMIN_SYNCHRONISATION,
                    "MES_PARCELLES_VIGNES" + EXT_geojson)
            # Retrouver le champ du nom de parcelle choisi
            LE_CHAMP_NOM_VIGNE_MP = \
                self.AttributMesParcellesCombo.currentText()
            traitementDupliquer_nom_parcelle(nom_vignes_mini_attributs,
                                             nom_vignes, LE_CHAMP_NOM_VIGNE_MP)
            toutes_vignes = QgsVectorLayer(nom_vignes,
                    MonParcellaire_attr_MP, "ogr")
            monProjet.addMapLayer(toutes_vignes, False)
            nouveauGroupeMP.addLayer(toutes_vignes)
        except:
            monPrint("Vecteur {0} ne convient pas pour gerer attribut pour"
                     "Mon Parcellaire la sélection des vignes".
                     format(nom_vignes_tous_attributs), T_ERR)
            erreurTraitement("Gestion des attributs de vignes")
        try:
            # Si demandé, retrouver les orientations
            if self.Orientation_checkBox.isChecked():
                CHOIX_ORIENTATION = "YES"
            else:
                CHOIX_ORIENTATION = "NO"
            if CHOIX_ORIENTATION == "YES":
                _, _, nom_vignes_orientees_modele = nommagesGPKG(
                    REPERTOIRE_GPKG,
                    MP_ORIENTE_MODELE_DANS_GPKG)
                monProjet, nouveauGroupeOrientation = \
                    self.ouvrirProjetETGroupe(MonParcellaire_ORIENTATION)
                orientation_centroide = QgsVectorLayer(
                    nom_vignes_orientees_modele,
                    "Modèle des " + MonParcellaire_ORIENTATION,
                    'ogr')
                monProjet.addMapLayer(orientation_centroide, False)
                nouveauGroupeOrientation.addLayer(orientation_centroide)
                nom_vignes_orientees = os.path.join(
                    CHEMIN_SYNCHRONISATION,
                    MonParcellaire_ORIENTE + EXT_geojson)
                traitementJointureOrientation(nom_vignes,
                                              nom_vignes_orientees_modele,
                                              nom_vignes_orientees)
                vignes_orientees = QgsVectorLayer(
                    nom_vignes_orientees,
                    MonParcellaire_ORIENTE,
                    "ogr")
                monProjet.addMapLayer(vignes_orientees, False)
                nouveauGroupeOrientation.addLayer(vignes_orientees)
                return nom_vignes_orientees
        except:
            monPrint(
                "Vecteur {0} ne convient pas pour joindre les orientations".
                format(nom_vignes_orientees_modele), T_ERR)
            erreurTraitement("Orientation vignes")
        return nom_vignes

    def slotTraiterRepertoireGPKGJointure(self):
        """ Gestion la sauvegarde du GPKG : trois cas de
        frequences de sauvegarde,
        Gestion des synchronisation Mes Parcelles Orientation
        Gestion de la jointure
        """
        monPrint(self.tr(
            "Contrôle répertoire, sauvegarde GPKGs"
            " et jointure ... Version {0}".
            format(APPLI_VERSION)))
        # Utiliser les dernières saisies
        REPERTOIRE_GPKG = self.Repertoire_lineEdit.text()
        FREQUENCE_SAUVEGARDE = self.FrequenceSauvegarde_comboBox.currentText()
        CHOIX_JOINTURE = "YES" if self.Jointure_checkBox.isChecked() else "NO"
        if self.Mes_Parcelles_checkBox.isChecked():
            CHOIX_MES_PARCELLES = "YES"
        else:
            CHOIX_MES_PARCELLES = "NO"
        CHOIX_SUITE = "YES" if self.Suite_checkBox.isChecked() else "NO"
        self.ecrireSettings()
        ###############
        # Sauvegardes
        ###############
        presenceObligatoire = True
        CHEMIN_VECTEUR_GPKG, cheminCompletParcelle = \
            self.sauvergardeSelonFrequence(
                REPERTOIRE_GPKG, MonParcellaire_GPKG,
                FREQUENCE_SAUVEGARDE, MonParcellaire_SAV,
                presenceObligatoire, MonParcellaire_PAR)
        CHEMIN_RASTER_GPKG, _ = self.sauvergardeSelonFrequence(
            REPERTOIRE_GPKG, MesFondsDePlan_GPKG,
            LISTE_FREQUENCE_SAUVEGARDE[3], MonParcellaire_SAV)
        CHEMIN_IEA_GPKG, _ = self.sauvergardeSelonFrequence(
            REPERTOIRE_GPKG, MesIAE_GPKG,
            FREQUENCE_SAUVEGARDE, MonParcellaire_SAV)
        # Sauver tous les projets
        nomProjetRecherches = os.path.join(REPERTOIRE_GPKG, '*' + EXT_qgz)
        listeProjetTriee = sorted(glob.glob(nomProjetRecherches))
        # monPrint(self.tr("Liste des projets QGIS {0}".
        # format(listeProjetTriee)))
        for monProjet in listeProjetTriee:
            nomCourtprojet = os.path.basename(monProjet)
            _, _ = self.sauvergardeSelonFrequence(
                REPERTOIRE_GPKG, nomCourtprojet,
                FREQUENCE_SAUVEGARDE, MonParcellaire_SAV)
        ###############
        # Jointure
        ###############
        if CHOIX_JOINTURE == "YES":
            # Déterminer le nom de la jointure (plusieurs extensions)
            jointureChoisie = self.rechercherExtensionEncodage(REPERTOIRE_GPKG)
            if jointureChoisie is not None:
                if CHOIX_MES_PARCELLES == "YES":
                    cheminCompletImporteMesParcelle = \
                        self.extraireVignesMesParcelles()
                    traitementSauverGPKGEcraserCouche(
                        cheminCompletImporteMesParcelle,
                        CHEMIN_VECTEUR_GPKG, MonParcellaire_PAR)
                CHEMIN_JOINTURE, attributsAJoindreOrdonne, aff_sans_suite = \
                    self.fusionnerJointure(cheminCompletParcelle,
                                           jointureChoisie)
                nomCourtJointure = os.path.basename(CHEMIN_JOINTURE)
                REPERTOIRE_JOINTURE = os.path.dirname(CHEMIN_JOINTURE)
                _, _ = self.sauvergardeSelonFrequence(REPERTOIRE_JOINTURE,
                    nomCourtJointure,
                    LISTE_FREQUENCE_SAUVEGARDE[0],
                    MonParcellaire_SAV,
                    presenceObligatoire)

                if CHOIX_SUITE == "YES":
                    # Récupérer la cave pour apport : jointure supplémentaire
                    nom_cave_pour_apport = os.path.join(REPERTOIRE_GPKG,
                                           MonParcellaire_JOI_CAVE + EXT_csv)
                    if os.path.isfile(nom_cave_pour_apport):
                        monPrint("= Info = Jointure pour cave d'apport: {}".
                                 format(nom_cave_pour_apport))
                        monProjet, nouveauGroupeCaveApport = \
                            self.ouvrirProjetETGroupe(
                                MonParcellaire_AFF_SANS_SUITE_CAVE)
                        _, csv, nomCsv = self.rechercherDelimiteurJointure(
                            nom_cave_pour_apport, "No Pandas")
                        monProjet.addMapLayer(csv, False)
                        nouveauGroupeCaveApport.addLayer(csv)
                        CHEMIN_SYNCHRONISATION = quel_chemin_synchro(
                            REPERTOIRE_GPKG,
                            REP_SYN)
                        affectation_sans_suite_mais_cave = os.path.join(
                            CHEMIN_SYNCHRONISATION,
                            MonParcellaire_AFF_SANS_SUITE_CAVE + EXT_geojson)
                        traitementJointureAttributListe(
                            aff_sans_suite,
                            csv, affectation_sans_suite_mais_cave)
                        # Ouvrir le resultat
                        sans_suite_et_cave = QgsVectorLayer(
                            affectation_sans_suite_mais_cave,
                            MonParcellaire_AFF_SANS_SUITE_CAVE, "ogr")
                        monProjet.addMapLayer(sans_suite_et_cave, False)
                        nouveauGroupeCaveApport.addLayer(sans_suite_et_cave)
                        self.affecterVignesSuites(
                            MonParcellaire_AFF_SANS_SUITE_CAVE + EXT_geojson,
                            'OUI')
                    else:
                        # Pour Rab on peut rajouter OUI
                        # mais il faut importer l'attribut "cave pour apport"
                        self.affecterVignesSuites(
                            MonParcellaire_AFF_SANS_SUITE + EXT_geojson)
                        # 'OUI')
                monPrint(self.tr("Fin : vérification répertoire,"
                                 " sauvegarde GPKGs et"
                                 " jointure {0} pour des attributs {1}".
                    format(nomCourtJointure, attributsAJoindreOrdonne)), T_OK)
            else:
                monPrint(self.tr(
                    "Fin : vérification répertoire - pas de jointure et"
                    " sauvegarde GPKGs"),
                    T_OK)
        else:
            monPrint(self.tr("Fin : vérification répertoire et"
                             " sauvegarde GPKGs"),
                     T_OK)

    def affecterVignesSuites(self, 
            source=MonParcellaire_AFF_SANS_SUITE + EXT_geojson,
            choix_cave_pour_apport='NON',
            cible=MonParcellaire_SUI + SEP_U + 'SANS_superficie' + EXT_geojson
                             ):
        """ Deviner les affectations pour les vignes suites
        (mais aussi cepage, orientation et Cave pour apport
        """
        REPERTOIRE_GPKG = self.Repertoire_lineEdit.text()
        CHEMIN_SYNCHRONISATION = quel_chemin_synchro(REPERTOIRE_GPKG, REP_SYN)
        if choix_cave_pour_apport == 'OUI':
            monPrint("{} = Traiter la cave d'apport.".format(E_CLAP))
        else:
            monPrint("{} = Ne pas traiter la cave d'apport.".format(E_CLAP))
        if not os.path.isfile(source):
            source = os.path.join(CHEMIN_SYNCHRONISATION, source)
        if not os.path.isfile(cible):
            cible = os.path.join(CHEMIN_SYNCHRONISATION, cible)
        monProjet, nouveauGroupeSUITE = self.ouvrirProjetETGroupe(
            MonParcellaire_SUI)
        monPrint("Traitement vignes suites ... Version {} module {}".
                 format(APPLI_VERSION, __name__))
        dfAffectation = gpd.read_file(source)
        dfAffectation["suite"] = "Non"
        # dump_df(dfAffectation, "Affect")

        # Supprimer les parcelles sans nom
        available_parcelles = dfAffectation['nom'].sort_values().unique()
        print("= Info = Nombre de parcelles uniques {}.".
              format(len(available_parcelles)))
        if (len(available_parcelles) == 1):
            monPrint("Attention, trop peu de vignes après la jointure : as-tu"
                     "bien choisi l'attribut qui nomme les parcelles dans Mes "
                     "Parcelles : code_vigne ou nom_parcelle ?")
            LE_CHAMP_NOM_VIGNE_MP = \
                self.AttributMesParcellesCombo.currentText()
            erreurAttributMesParcelles(LE_CHAMP_NOM_VIGNE_MP)
        else:
            print("= Info = Les parcelles {}.".format(available_parcelles))
        nb_double = 0
        der_liste = []
        inconsistants = []
        for pos, une_parcelle in enumerate(available_parcelles):
            # Trappe pour debug
            # if pos > 30:
            #   break
            # if une_parcelle != "F0001CO24":
            #    continue
            if une_parcelle == "NULL":
                print("{} = On Saute des NULL.".format(E_WARNING))
                continue
            df_une_parcelle = dfAffectation[
                (dfAffectation['nom'] == une_parcelle)]
            if len(df_une_parcelle) > 1:
                nb_double = nb_double + 1
                aPrint = "{} {}ème DOUBLE entité pour la parcelle {}".\
                    format(E_WARNING, nb_double, une_parcelle)
                aPrint = aPrint + "dans Mes Parcelles qui doit être corrigé"
                monPrint(aPrint)
                continue
            affectation_coopviti = df_une_parcelle['Code validation'].values[0]
            cepage = df_une_parcelle['Cépage'].values[0]
            pre_orientation = df_une_parcelle['orientation'].values[0]
            try:
                orientation = int(pre_orientation)
            except (ValueError, TypeError):
                orientation = 9999
            # Rapprochement des vignes suites (A B C D) avec vigne principale
            suite = "Non"
            cave = "Inconnue"
            if choix_cave_pour_apport == 'OUI':
                cave = df_une_parcelle['Cave pour apport'].values[0]
                # monPrint("Pour la parcelle {} la cave est {}".
                # format(une_parcelle, cave))

            if affectation_coopviti is None or \
                    affectation_coopviti == "nan" or \
                    len(affectation_coopviti) <= 0:
                # Gerer aussi les _A _B _C
                caractere_suite = 0
                if une_parcelle[-1] in ["A", "B", "C", "D", "E", "F"] or \
                        une_parcelle[-1] in ["a", "b", "c", "d", "e", "f"]:
                    caractere_suite = -1
                    if une_parcelle[-2:] in ["_A", "_B", "_C",
                                             "_D", "_E", "_F"] or \
                            une_parcelle[-2:] in ["_a", "_b", "_c",
                                                  "_d", "_e", "_f"]:
                        caractere_suite = -2
                    if une_parcelle[-2:] in ["-A", "-B", "-C",
                                             "-D", "-E", "-F"] or \
                            une_parcelle[-2:] in ["-a", "-b", "-c",
                                                  "-d", "-e", "-f"]:
                        caractere_suite = -2

                if caractere_suite < 0:     # parcelle suite possible
                    # parcelle_possible = une_parcelle[0:caractere_suite]
                    if une_parcelle[0:caractere_suite] == der_liste[0]:
                        monPrint("== Parcelle suite "
                            "{} est rapprochée de {} pour les valeurs {}".
                            format(une_parcelle, der_liste[0], der_liste))
                        affectation_coopviti = der_liste[1]
                        cepage = der_liste[2]
                        if orientation == 9999:
                            orientation = int(der_liste[3])
                        if choix_cave_pour_apport == 'OUI':
                            cave = der_liste[4]
                        suite = "Oui"
                    else:
                        affectation_coopviti = "Inconnue"
                        cepage = "Inconnu"
                        if orientation == 9999:
                            orientation = 0
                        cave = "Non rapprochée"
                        suite = "Non rapprochée"

                    # Mémoriser Affectation
                    if choix_cave_pour_apport == 'OUI':
                        aP = "= Info = Vignes suite "
                        aP = aP + "{} == Affectation {} Cépage {}".\
                            format(une_parcelle, affectation_coopviti, cepage)
                        aP = aP + "Orientation {}.Cave {}".\
                            format(orientation, cave)
                        monPrint(aP)
                    else:
                        monPrint("= Info = Vignes suite "
                          "{} == Affectation {} Cépage {} Orientation {}".
                          format(une_parcelle, affectation_coopviti, cepage,
                                 orientation))

                    dfAffectation.loc[dfAffectation["nom"] == une_parcelle,
                                      "Code validation"] = affectation_coopviti
                    dfAffectation.loc[dfAffectation["nom"] == une_parcelle,
                                      "Cépage"] = cepage
                    dfAffectation.loc[dfAffectation["nom"] == une_parcelle,
                                      "orientation"] = orientation
                    dfAffectation.loc[dfAffectation["nom"] == une_parcelle,
                                      "suite"] = suite
                    # JH si choix_cave_pour_apport
                    if choix_cave_pour_apport == 'OUI':
                        dfAffectation.loc[dfAffectation["nom"] == une_parcelle,
                                          "Cave pour apport"] = cave
                else:
                    aP = "{} BASES INCONSISTANTES == Parcelle {}".\
                        format(E_WARNING, une_parcelle)
                    aP = aP + " (non A B C D E OU F) sans affectation, "
                    aP = aP + "cépage et orientation ne sont pas conservés"
                    monPrint(aP)
                    dfAffectation.drop(
                        dfAffectation.loc
                        [dfAffectation["nom"] == une_parcelle].index,
                        inplace=True)
                    # Ecrire une liste sans affectations
                    inconsistants.append(une_parcelle)

            # Memoriser si non suite
            if une_parcelle[-1] not in ["A", "B", "C", "D",
                                        "E", "F", "a", "b",
                                        "c", "d", "e", "f"]:
                if choix_cave_pour_apport == 'OUI':
                    der_liste = [une_parcelle, affectation_coopviti,
                                 cepage, str(orientation), cave]
                else:
                    der_liste = [une_parcelle, affectation_coopviti,
                                 cepage, str(orientation)]
                # monPrint("= Info = {} Derniere memorisée {}".
                # format(une_parcelle, der_liste))
        dfAffectation.to_file(cible, driver="GeoJSON")
        if len(inconsistants) > 0:
            monPrint("{} vignes de Mes Parcelles ni affectable ni suite : {}".
                     format(len(inconsistants), inconsistants), T_WAR)
        # Calculer superficie des vignes
        cible_finale = os.path.join(CHEMIN_SYNCHRONISATION,
                                    MonParcellaire_AFF + EXT_geojson)
        traitementCalculerSuperficie(cible, cible_finale)
        # kml en GPS et GPKG en 2154
        cible_kml = os.path.join(CHEMIN_SYNCHRONISATION,
                                 MonParcellaire_AFF + EXT_kml)
        traitementGarderChamps(cible_finale,
                               cible_kml, ["nom", "Code validation"])
        CHEMIN_VECTEUR_GPKG = os.path.join(REPERTOIRE_GPKG,
                                           MonParcellaire_GPKG)
        traitementSauverGPKGEcraserCouche(cible_finale,
                                          CHEMIN_VECTEUR_GPKG,
                                          MonParcellaire_AFF)
        affectation_suite = QgsVectorLayer(cible_finale,
                    MonParcellaire_SUI.upper(), "ogr")
        monProjet.addMapLayer(affectation_suite, False)
        nouveauGroupeSUITE.addLayer(affectation_suite)

    def filterAtOnce(self, fieldName, operator, fieldValue):
        # Très fortement inspiré de l'extension FilterAtOnce
        # (id 1968, https://github.com/muratkendir/FilterLayersAtOnce)
        # Thanks muratkendir
        # Inutile de faire un clear avant
        layers = QgsProject.instance().layerTreeRoot().children()
        # fieldName = self.dlg.lineEdit_fieldName.text()
        # operator = self.dlg.comboBox.currentText()
        # fieldValue = self.dlg.lineEdit_value.text()
        if fieldName == '' or fieldValue == '':
            monPrint("{} Attention, il manque field name or value.".
                     format(E_WARNING))
        else:
            for katman in layers:
                # Eviter de filtrer "tree layer group"
                try:
                    layer_name = katman.layer().name()
                    # monPrint(katman.type() + ' is layer ?')
                    try:
                        f = fieldName
                        o = operator
                        v = fieldValue
                        sub = str(f) + ' ' + str(o) + ' ' + "'" + str(v) + "'"
                        katman.layer().setSubsetString(sub)
                        # print(layer_name + ' couche filtrée.')
                    except:
                        print(layer_name + " n'est pas filtrée.")
                except:
                    print("Une couche n'est pas filtrée.")
        return

    def imprimerSelection(self, selection=[]):
        """ Filtrer les couches sur le nom présents dans selection
        (inspiration de Filter at once)
        Imprimer l'atlas de chaque selection
        """
        self.ecrireSettings()
        _, _, _, _, _, _, _, _, REP_GPKG, _, _, _, _, _, DERNIER_ATLAS =\
            self.lireSettings()
        if selection == []:
            impressionSelectionnes =\
                self.NomsImprimables_listWidget.selectedItems()
            impressionListe = []
            for p in range(len(impressionSelectionnes)):
                impressionListe.append(str(
                    self.NomsImprimables_listWidget.selectedItems()[p].text()))
            if impressionListe != []:
                selection = impressionListe
        # monPrint("Début impression de atlas {} pour la sélection : {}".
        # format(self.Imprimer_lineEdit_Nom.text(), selection))
        REP_GPKG = self.Repertoire_lineEdit.text()
        repertoire_print = os.path.join(REP_GPKG, "PRINT")
        if not os.path.isdir(repertoire_print):
            os.mkdir(repertoire_print)

        for nom in selection:
            # monPrint("Filtrer sur le nom : {}".format(nom))
            # Filtrer les couches du projet ? en batch
            self.filterAtOnce("nom", "like", nom + "%")
            pdf_print = os.path.join(
                repertoire_print, nom + " " + DERNIER_ATLAS + EXT_pdf)
            monPrint("Imprimer atlas du nom : {} dans le pdf {}".
                     format(nom, pdf_print))
            processing.run("native:atlaslayouttopdf",
                           {'LAYOUT': DERNIER_ATLAS, 'COVERAGE_LAYER': None,
                            'FILTER_EXPRESSION': '', 'SORTBY_EXPRESSION': '',
                            'SORTBY_REVERSE': False, 'LAYERS': None,
                            'DPI': None, 'FORCE_VECTOR': False,
                            'FORCE_RASTER': False, 'GEOREFERENCE': True,
                            'INCLUDE_METADATA': True, 'DISABLE_TILED': False,
                            'SIMPLIFY': True, 'TEXT_FORMAT': 1,
                            'IMAGE_COMPRESSION': 0, 'OUTPUT': pdf_print})
        monPrint("Fin des impression de la liste : {}".format(selection))
        return

    def imprimerTous(self):
        """ Retrouver tous les noms imprimables et appeler imprimerSelection
        """
        self.ecrireSettings()
        _, _, _, _, _, _, _, _, REP_GPKG, _, _, _, LISTE_TOUS_IMP, _, _ =\
            self.lireSettings()
        # monPrint("Début impression de tous retrouver dans : {}".
        # format(LISTE_TOUS_IMP))
        if LISTE_TOUS_IMP != ["Pas de noms imprimables"]:
            self.imprimerSelection(LISTE_TOUS_IMP)
            # monPrint("Fin impression de tous : {}".format(LISTE_TOUS_IMP))
        else:
            monPrint("{} dans le répertoire {} : aucune impression".
                     format("Pas de noms imprimables", REP_GPKG))
        return

    def consoliderTerroir(self, terroir_gpkg="IFV_sols_terroir" + EXT_gpkg,
            couche_terroir_gpkg="sols terroirs",
            affectation_gpkg=MonParcellaire_GPKG,
            couche_affectation_gpkg=MonParcellaire_AFF,
            cible="CONSOLIDE" + SEP_U + MP_PAR + SEP_U + MP_TER + EXT_geojson):
        """ La sauvergarde du shp en gpkg n'est pas automatisé
         Créer une intersection de "sols terroirs" par "affectations"
         Rechercher surface des terroir dans parcelle et leur % pour
         classer et pondérer les informtions terroirs
         Lancer la consolidation finale
        """
        REP_GPKG = self.Repertoire_lineEdit.text()
        CHEMIN_SYNCHRONISATION = quel_chemin_synchro(REP_GPKG, REP_SYN)
        REPERTOIRE_COMMUN = os.path.dirname(REP_GPKG)
        REPERTOIRE_TERROIR = os.path.join(REPERTOIRE_COMMUN,
                                          NOM_REPERTOIRE_TERROIR)
        # Nommage et sauvegarde terroir
        _, _, intersection = nommagesGPKG(REP_GPKG,
                                          couche_affectation_gpkg,
                                          affectation_gpkg, True)
        # Assert Terroir existe pour vérouiller
        # seul cas FRONTON et exception explicite
        _, _, terroirs = nommagesGPKG(REPERTOIRE_TERROIR,
                                      couche_terroir_gpkg,
                                      terroir_gpkg, True)
        # TODO: verifier le bon encodage UTF-8

        if not os.path.isfile(cible):
            cible_complet = os.path.join(REPERTOIRE_TERROIR, cible)
        monProjet, nouveauGroupeTERROIR = self.ouvrirProjetETGroupe(MP_TER)
        traitementIntersection(terroirs, intersection, cible_complet)

        # Champs superfie de chaque UT dans chaque parcelle et % des morceaux
        consolide_surface = os.path.join(REPERTOIRE_TERROIR,
                                         "SURFACE_" + cible)
        traitementCalculerSuperficie(cible_complet, consolide_surface,
                                     'surface_ut_dans_parcelle')
        # Ajout du champ affectation simplifiée
        # consolide_affectation=os.path.join(REPERTOIRE_TERROIR,
        # "AFFECTATION_"+cible)
        # traitementCalculerAffectationSimplifiee(consolide_surface,
        # consolide_affectation)
        # Afficher consolidation
        consolide_terroir = QgsVectorLayer(consolide_surface,
                    MP_TER.upper(), "ogr")
        monProjet.addMapLayer(consolide_terroir, False)
        nouveauGroupeTERROIR.addLayer(consolide_terroir)
        # Verifier presence et passage eventuel en UTF
        csvChoisie = self.rechercherExtensionEncodage(REPERTOIRE_TERROIR,
                                                      "UTs_par_parcelles")
        dfT = pd.read_csv(csvChoisie,
            sep="{}".format(","))  # encoding="utf-8")
        # Creer la synthese
        NOM_COURT_SYNTHESE = "Parcelle Coopviti Mes Parcelles Orientation" + \
            SEP_U + 'SUP' + SEP_U + str(LE_POURCENTAGE_IGNORE) + EXT_csv
        CSV_SYNTHESE = os.path.join(CHEMIN_SYNCHRONISATION, NOM_COURT_SYNTHESE)
        mon_csv_synthese, writer = initaliser_synthese_csv(CSV_SYNTHESE)
        # dump_df(dfT, cible)
        # monPrint("Les types des colonnes sont : {}".format(dfT.dtypes))
        available_parcelles = dfT['nom'].sort_values().unique()
        monPrint("= Info = Nombre de parcelles uniques {}.".
                 format(len(available_parcelles)))
        un_seul = plusieurs = sans_terroir = 0
        max_sous_parcelle = 0
        for pos, une_parcelle in enumerate(available_parcelles):
            # Trappe pour debug
            # if une_parcelle != "F0001CO24":
            #    continue
            p = une_parcelle
            pour = LE_POURCENTAGE_IGNORE
            # print("Position {} parcelle {}".format(pos, p))
            df_une = dfT[
                (dfT['nom'] == p) & (dfT['pourcent_ut_dans_parcelle'] > pour)]
            # print("Colonnes dans df Parcelle {}".format(list(df_une.columns)))
            # print("df Parcelle orientation {}".format(df_une['orientation']))
            info_terroir = df_une[['pourcent_ut_dans_parcelle',
                'CODE_UT', 'N_REG_SOL', 'NOMENCLATU', 'RUM',
                'DRAINAGE', 'VIGUEUR', 'Surface Encepagée',
                'Code validation', 'Cépage', 'Porte Greffe',
                'orientation']].sort_values(ascending=False,
                by='pourcent_ut_dans_parcelle').values.tolist()
            if len(df_une) > 1:
                available_pourcentage_parcelles = df_une[
                    'pourcent_ut_dans_parcelle'].sort_values(ascending=False)
                plusieurs = plusieurs + 1
                if len(df_une) > max_sous_parcelle:
                    max_sous_parcelle = len(df_une)
                    if plusieurs in [100, 800]:
                        print("Parcelle {} a plusieurs cas de terroirs {} et"
                              "les pourcentages sont {}".
                              format(une_parcelle,
                                     len(df_une),
                                     list(available_pourcentage_parcelles)))
                        print("Parcelle {} et info terroirs {}".
                              format(une_parcelle, info_terroir))
            elif len(df_une) == 1:
                un_seul = un_seul + 1
            else:
                # Cas bizarre
                sans_terroir = sans_terroir + 1
                monPrint("{} == Parcelle {} aucune information terroir.".
                         format(U_TERROIR, une_parcelle))
                continue
            # Ecrire dans synthese
            ajoute_une_consolidation(writer, une_parcelle, info_terroir)

        aPrint = "=== {} parcelles avec un seul terroir, {} avec plusieurs".\
                 format(un_seul, plusieurs)
        aPrint = aPrint + " (max vaut {}) et {} sans information terroir.".\
                          format(max_sous_parcelle, sans_terroir)
        monPrint(aPrint)
        mon_csv_synthese.close()
        # Jointure des affectations et de la synthese terroir
        cible_terroir_court = "TERROIR_AFFECTES" + EXT_geojson
        cible_terroir = os.path.join(REPERTOIRE_TERROIR, cible_terroir_court)
        sans_terroir = os.path.join(REPERTOIRE_TERROIR,
                                    "PARCELLE_SANS_TERROIR" + EXT_geojson)
        traitementJointureAttributs(intersection, CSV_SYNTHESE,
                                    cible_terroir, sans_terroir)
        consolide_terroir = QgsVectorLayer(cible_terroir,
                    cible_terroir_court, "ogr")
        monProjet.addMapLayer(consolide_terroir, False)
        nouveauGroupeTERROIR.addLayer(consolide_terroir)

        monPrint("Fin consolidation terroir {}, parcelles sans terroir {}.".
                format(cible_terroir, sans_terroir), T_OK)
        return

